// Hover and focus tooltips for items and augments. Description text is generated by
// scripts/sync-tooltips.py and loaded per language on first use, so it costs nothing
// until someone actually hovers an icon.
import {t, getLanguage, getLocale} from './i18n.js';
import {augmentAsset} from './augment-assets.js';

const escape = value =>
  String(value ?? '').replace(
    /[&<>"']/g,
    char => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'})[char],
  );
const lines = text => escape(text).replace(/\n/g, '<br>');
const RARITY_LABELS = {silver: 'Bạc', gold: 'Vàng', prismatic: 'Lăng Kính'};
const GAP = 10;

export function tooltipContent(kind, id, data, language = getLanguage()) {
  if (kind === 'item') {
    const item = data?.item?.[id];
    if (!item) return null;
    const price = item.price
      ? `<span class="tooltip-meta">${new Intl.NumberFormat(getLocale()).format(item.price)} ${t('vàng')}</span>`
      : '';
    return `<div class="tooltip-head"><strong>${escape(item.name)}</strong>${price}</div>${item.text ? `<p>${lines(item.text)}</p>` : ''}`;
  }
  if (kind === 'augment') {
    const asset = augmentAsset(id, language);
    if (!asset) return null;
    const text = data?.augment?.[id];
    const rarity = asset.rarity
      ? `<span class="tooltip-rarity augment-${asset.rarity}">${t(RARITY_LABELS[asset.rarity])}</span>`
      : '';
    return `<div class="tooltip-head"><strong>${escape(asset.name)}</strong>${rarity}</div>${text ? `<p>${lines(text)}</p>` : `<p class="tooltip-muted">${t('Chưa có mô tả cho augment này.')}</p>`}${text?.includes('X') ? `<p class="tooltip-note">${t('X: giá trị thay đổi theo cấp hoặc trận, client không cung cấp số liệu.')}</p>` : ''}`;
  }
  return null;
}

const cache = new Map();
function loadTexts(language) {
  if (!cache.has(language))
    cache.set(
      language,
      import(language === 'en' ? './tooltip-text-en.js' : './tooltip-text-vi.js')
        .then(module => module.default)
        .catch(() => ({item: {}, augment: {}})),
    );
  return cache.get(language);
}

function place(tip, target) {
  const box = target.getBoundingClientRect();
  const width = tip.offsetWidth,
    height = tip.offsetHeight;
  const left = Math.min(Math.max(GAP, box.left + box.width / 2 - width / 2), window.innerWidth - width - GAP);
  const above = box.top - height - GAP;
  const top = above >= GAP ? above : box.bottom + GAP;
  tip.style.transform = `translate(${Math.round(left)}px, ${Math.round(top + window.scrollY)}px)`;
  tip.dataset.side = above >= GAP ? 'top' : 'bottom';
}

export function initTooltips(root = document) {
  const tip = document.createElement('div');
  tip.id = 'game-tooltip';
  tip.className = 'game-tooltip';
  tip.setAttribute('role', 'tooltip');
  tip.hidden = true;
  document.body.append(tip);
  let current = null;
  const hide = () => {
    current = null;
    tip.hidden = true;
    tip.classList.remove('is-visible');
  };
  async function show(target) {
    current = target;
    const kind = target.dataset.tipKind,
      id = Number(target.dataset.tipId);
    const data = await loadTexts(getLanguage());
    if (current !== target) return;
    const content = tooltipContent(kind, id, data);
    if (!content) return hide();
    tip.innerHTML = content;
    tip.hidden = false;
    place(tip, target);
    tip.classList.add('is-visible');
    target.setAttribute('aria-describedby', tip.id);
  }
  const targetOf = event => event.target.closest?.('[data-tip-kind][data-tip-id]');
  root.addEventListener('pointerover', event => {
    const target = targetOf(event);
    if (target && target !== current) show(target);
  });
  root.addEventListener('pointerout', event => {
    const target = targetOf(event);
    if (target && !target.contains(event.relatedTarget)) {
      target.removeAttribute('aria-describedby');
      hide();
    }
  });
  root.addEventListener('focusin', event => {
    const target = targetOf(event);
    if (target) show(target);
  });
  root.addEventListener('focusout', hide);
  window.addEventListener('scroll', hide, {passive: true});
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') hide();
  });
}
